// Get namedays for a specific month and day
// Returns pointer to names string (without MMDD: prefix), or nullptr if not found
// Caller should copy the result as it points to static buffer
const char* namedays_get(uint8_t month, uint8_t day) {
    if (month < 1 || month > 12 || day < 1 || day > 31) return nullptr;
    
    // Build search key "MMDD:"
    char key[6];
    snprintf(key, sizeof(key), "%02d%02d:", month, day);
    
    // Search in data
    const char* p = NAMEDAY_DATA;
    while (*p) {
        if (strncmp(p, key, 5) == 0) {
            // Found - return pointer after the colon
            const char* names = p + 5;
            // Find end of line
            static char result[100];
            int i = 0;
            while (*names && *names != '\n' && i < 99) {
                result[i++] = *names++;
            }
            result[i] = '\0';
            return result;
        }
        // Skip to next line
        while (*p && *p != '\n') p++;
        if (*p == '\n') p++;
    }
    return nullptr;
}

// Get first name only (for display on small screen)
const char* namedays_get_first(uint8_t month, uint8_t day) {
    const char* names = namedays_get(month, day);
    if (!names) return nullptr;
    
    static char first[20];
    int i = 0;
    while (names[i] && names[i] != ',' && i < 19) {
        first[i] = names[i];
        i++;
    }
    first[i] = '\0';
    return first;
}
